    ('island-thetis-island', 'Thetis Island', 'island', 48.998333, -123.680833, 'Gulf Islands', 'No visitor overview is available from the BC Geographical Names Office; its record confirms the official island name and location.', 'https://apps.gov.bc.ca/pub/bcgnws/names/14969.html', 'BC Geographical Names Office', '21693', NULL),
    ('island-valdes-island', 'Valdes Island', 'island', 49.070556, -123.651667, 'Gulf Islands', 'No visitor overview is available from the BC Geographical Names Office; its record confirms the official island name and location.', 'https://apps.gov.bc.ca/pub/bcgnws/names/23524.html', 'BC Geographical Names Office', '28944', NULL),
    ('island-vargas-island', 'Vargas Island', 'island', 49.186389, -125.988056, 'West Coast Islands', 'No visitor overview is available from the BC Geographical Names Office; its record confirms the official island name and location.', 'https://apps.gov.bc.ca/pub/bcgnws/names/24352.html', 'BC Geographical Names Office', '29648', NULL),
    ('national-gulf-islands-national-park-reserve', 'Gulf Islands National Park Reserve', 'national', 48.66552, -123.407929, 'Gulf Islands', 'Across the southern Gulf Islands, this reserve protects island habitats and small marine areas in the Salish Sea. Sheltered channels support seals, otters, orcas and porpoises, while eagles and seabirds pass above the water.', 'https://parks.canada.ca/pn-np/bc/gulf', 'Parks Canada', NULL, NULL),
    ('national-pacific-rim-national-park-reserve', 'Pacific Rim National Park Reserve', 'national', 49.060406, -125.722799, 'West Coast', 'On Vancouver Island’s west coast, Pacific Rim brings together three distinct areas: sandy beaches and rainforest at Long Beach, boat-access islands in Barkley Sound, and the backcountry West Coast Trail. The reserve protects coastal forest and nearshore marine habitat.', 'https://parks.canada.ca/pn-np/bc/pacificrim', 'Parks Canada', NULL, NULL),
    ('provincial-arbutus-grove-park', 'Arbutus Grove Park', 'provincial', 49.248767, -124.15096, 'Central Island', 'This park protects a representative stand of arbutus, Canada''s only native broadleaf evergreen. BC Parks describes the grove as a quiet nature-viewing spot used by local hikers; the site has no facilities or road access.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '465', NULL),
    ('provincial-artlish-caves-park', 'Artlish Caves Park', 'provincial', 50.139233, -126.905802, 'North Island', 'Artlish Caves protects nationally significant limestone karst, with large cave entrances, an underground river and old-growth forest. The area is remote and ecologically sensitive; BC Parks says caving is not recommended until a management plan is in place.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '472', NULL),
    ('provincial-au-welnew-john-dean-park', 'Ƚáuˌwelṉew̱ / John Dean Park', 'provincial', 48.614651, -123.448195, 'South Island', 'Atop Mount Newton, this park looks across the Saanich Peninsula, Gulf Islands and Cascade Mountains. It protects remaining old-growth Douglas fir and Garry oak on the peninsula, while the mountain and surrounding landscape hold cultural significance for First Nations.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '775', NULL),
    ('provincial-bamberton-park', 'Bamberton Park', 'provincial', 48.606087, -123.527194, 'South Island', 'A 225-metre sandy beach on Saanich Inlet anchors this small coastal park. Visitors come for swimming, shoreline views toward the Gulf Islands and Mount Baker, and a forested vehicle-accessible campground.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '482', NULL),
    ('provincial-beaver-point-park', 'Beaver Point Park', 'provincial', 48.770666, -123.402462, 'Gulf Islands', 'No visitor overview is available for Beaver Point Park on the current BC Parks page. See the official page for current visitor information.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '493', NULL),
    ('provincial-bellhouse-park', 'Bellhouse Park', 'provincial', 48.872178, -123.311921, 'Gulf Islands', 'This day-use park on Galiano Island looks across Active Pass toward Mayne Island and the Strait of Georgia. A short path through Garry oak meadow leads to a rocky shore, picnic spots and views of passing ferries and marine wildlife.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '496', NULL),
    ('provincial-big-bunsby-marine-park', 'Big Bunsby Marine Park', 'provincial', 50.107384, -127.509384, 'North Island', 'A boat-access marine park among the Bunsby Islands, set beside the Checleset Bay Ecological Reserve. Kayakers and boaters find sheltered anchorages, while low tides reveal pools of intertidal life; wilderness camping is possible on Big Bunsby Island.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '499', NULL),
    ('provincial-bodega-ridge-park', 'Bodega Ridge Park', 'provincial', 48.95753, -123.527773, 'Gulf Islands', 'A day-use ridge park on Galiano Island with a 4-kilometre crest and broad views over Trincomali Channel, Vancouver Island and the Strait of Georgia. Its trail crosses forest and cliff edge, with sandstone shoreline formations, wildflowers and raptor habitat below.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '5018', NULL),
    ('provincial-boyle-point-park', 'Boyle Point Park', 'provincial', 49.481834, -124.701753, 'Northern Gulf Islands', 'At the south end of Denman Island, a forest trail reaches viewpoints over Baynes Sound and Chrome Island Lighthouse. The shoreline attracts seals, sea lions and seabirds, and the park also protects older Douglas fir, cedar and hemlock forest.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '522', NULL),
    ('provincial-burgoyne-bay-park', 'Burgoyne Bay Park', 'provincial', 48.786286, -123.52386, 'Gulf Islands', 'Burgoyne Bay is part of a large connected conservation area on Salt Spring Island, protecting several at-risk ecosystems. Low-impact walks and viewpoints look over Burgoyne Bay, Mount Maxwell and Baynes Peak.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '5124', NULL),
    ('provincial-cape-scott-park', 'Cape Scott Park', 'provincial', 50.787271, -128.347821, 'North Island', 'At Vancouver Island''s northwestern tip, Cape Scott protects a vast stretch of rugged coast, remote beaches, estuaries, bogs and old-growth forest. Visitors explore by day hike or multi-day backpacking trip, including routes to San Josef Bay and Nels Bight.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '549', NULL),
    ('provincial-carmanah-walbran-park', 'Carmanah Walbran Park', 'provincial', 48.653549, -124.63134, 'South Island', 'The Carmanah and Walbran valleys contain some of Vancouver Island''s largest Sitka spruce and ancient western red cedars, within a protected old-growth forest system. Valley trails reach notable trees and waterways, though routes can be very muddy and demanding.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '555', NULL),
    ('provincial-chemainus-river-park', 'Chemainus River Park', 'provincial', 48.841582, -123.824338, 'South Island', 'This park addition follows the Chemainus River about 3 kilometres northwest of Duncan. It is cooperatively managed by the Cowichan Valley Regional District, so facilities and services may differ from other BC Parks sites.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '568', NULL),
    ('provincial-claud-elliott-lake-park', 'Claud Elliott Lake Park', 'provincial', 50.309538, -126.55756, 'North Island', 'This protected area sits in the upper Tsitika watershed, within a river system recognized for its importance to Vancouver Island fish. It helps conserve montane forest and winter habitat for deer and Roosevelt elk alongside neighboring ecological reserves.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '584', NULL),
    ('provincial-clayoquot-arm-park', 'Clayoquot Arm Park', 'provincial', 49.173482, -125.559739, 'Central Island', 'On Vancouver Island''s west coast, the park protects the lower Clayoquot River, Clayoquot Lake and forested slopes beside Kennedy Lake. Boat, canoe or kayak access opens onto old-growth Sitka spruce, sandy beaches, small islands and cultural sites.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '586', NULL),
    ('provincial-clayoquot-plateau-park', 'Clayoquot Plateau Park', 'provincial', 49.225058, -125.427969, 'Central Island', 'A high, remote plateau protects old-growth forest, rare plants, karst features, sinkholes and small lakes. There are no developed trails, and access is difficult, so visits are best suited to experienced backcountry travellers.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '587', NULL),
    ('provincial-collinson-point-park', 'Collinson Point Park', 'provincial', 48.861615, -123.36107, 'Gulf Islands', 'BC Parks identifies Collinson Point as a park established through private land acquisition. Its current visitor page provides little additional overview information; check the official page for updates before planning a visit.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '5186', NULL),
    ('provincial-cowichan-river-park', 'Cowichan River Park', 'provincial', 48.786474, -123.973295, 'South Island', 'This riverside park protects sections of the Cowichan River, a designated Canadian Heritage River known for salmon and steelhead. The area supports swimming, paddling, fishing, hiking and camping, with opportunities to enjoy the river corridor and its forested banks.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '605', NULL),
    ('provincial-dawley-passage-park', 'Dawley Passage Park', 'provincial', 49.145614, -125.78785, 'Central Island', 'Accessible by boat in Clayoquot Sound, Dawley Passage offers a quiet stop along Fortune Channel between Meares Island and Vancouver Island. Sheltered water draws paddlers and boaters, with opportunities for fishing, wildlife viewing and wilderness camping.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '617', NULL),
    ('provincial-denman-island-park', 'Denman Island Park', 'provincial', 49.564393, -124.815225, 'Northern Gulf Islands', 'This park protects forest and the Chicadee watershed within the uncommon Coastal Douglas-fir zone on Denman Island. The area also provides habitat for species at risk, including Taylor''s checkerspot butterfly.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '5412', NULL),
    ('provincial-dionisio-point-park', 'Dionisio Point Park', 'provincial', 49.005827, -123.574615, 'Gulf Islands', 'Boat-accessible Dionisio Point sits at the north end of Galiano Island beside Porlier Pass. Rocky headlands, sandstone shelves, beaches and flower meadows frame rich tidal habitat, with opportunities for paddling, fishing, wildlife viewing and walk-in camping.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '625', NULL),
    ('provincial-drumbeg-park', 'Drumbeg Park', 'provincial', 49.132142, -123.694782, 'Gulf Islands', 'On Gabriola Island, this coastal park overlooks Gabriola Passage and the Strait of Georgia. It protects Garry oak and Douglas-fir ecosystems, forest and marine habitat, where visitors can picnic, walk, dive and explore the shoreline.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '633', NULL),
    ('provincial-elk-falls-park', 'Elk Falls Park', 'provincial', 50.045138, -125.328763, 'North Island', 'A dramatic waterfall, forest trails and a salmon-rich river make Elk Falls a popular stop near Campbell River. Visitors can explore riverside viewpoints, fish in season and camp among the trees close to the Quinsam River and hatchery.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '652', NULL),
    ('provincial-englishman-river-falls-park', 'Englishman River Falls Park', 'provincial', 49.24728, -124.351679, 'Central Island', 'Two waterfalls descend through a deep canyon along the Englishman River, surrounded by lush old-growth and second-growth forest. The park offers a scenic place to walk beside the river and explore the forest north of Nanaimo.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '661', NULL),
    ('provincial-eves-park', 'Eves Park', 'provincial', 48.86121, -123.698262, 'South Island', 'No visitor overview is available for Eves Park on the current BC Parks page. See the official page for current visitor information.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '668', NULL),
    ('provincial-fillongley-park', 'Fillongley Park', 'provincial', 49.543569, -124.76203, 'Northern Gulf Islands', 'This quiet picnic park on northern Denman Island was once a developed estate before its land was donated to the province. Mature trees, gardens and shoreline create a calm setting for a short walk or afternoon by the water.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '674', NULL),
    ('provincial-flores-island-park', 'Flores Island Park', 'provincial', 49.272833, -126.165597, 'West Coast Islands', 'A large wilderness park in Clayoquot Sound, Flores Island offers coastal hiking, paddling, whale watching and beach camping. It protects old-growth Sitka spruce, salmon habitat, rocky shore, beaches and a range of coastal and marine ecosystems.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '680', NULL),
    ('provincial-fossli-park', 'Fossli Park', 'provincial', 49.248862, -124.949267, 'Central Island', 'On Sproat Lake''s Stirling Arm, this undeveloped day-use park has a short forest trail to an old homestead site. A grassy lakeside area and pebble beach offer a place to pause and take in the lake views.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '683', NULL),
    ('provincial-french-beach-park', 'French Beach Park', 'provincial', 48.392727, -123.942632, 'South Island', 'A broad lawn meets a sand-and-pebble beach on the Strait of Juan de Fuca, with views toward the Olympic Mountains. Forest trails and a campground add to the appeal, while spring whale migrations make the shoreline a popular place to watch the water.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '687', NULL),
    ('provincial-gabriola-sands-park', 'Gabriola Sands Park', 'provincial', 49.19393, -123.860367, 'Gulf Islands', 'Two sandy beaches join across a narrow isthmus between Taylor Bay and Pilot Bay on Gabriola Island. This popular day-use park has open lawns for picnics and swimming, and its beaches and shallows support shorebirds and marine life.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '688', NULL),
    ('provincial-gibson-marine-park', 'Gibson Marine Park', 'provincial', 49.263648, -126.073275, 'Central Island', 'This marine park beside Flores Island Park has sheltered anchorage in Matilda Inlet and a natural warm spring on the shore. A historic, unmaintained route connects the spring area with the sandy beaches at Whitesand Cove.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '693', NULL),
    ('provincial-gold-muchalat-park', 'Gold Muchalat Park', 'provincial', 49.866476, -126.10123, 'North Island', 'Northwest of Gold River, Gold Muchalat is an undeveloped wilderness area with opportunities for fishing, wildlife watching and rustic hiking. The park also protects winter habitat for Roosevelt elk and deer, plus salmon waters in the Muchalat River.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '703', NULL),
    ('provincial-goldstream-park', 'Goldstream Park', 'provincial', 48.475557, -123.542431, 'South Island', 'Close to Victoria, Goldstream combines old forest, waterfalls, river trails and seasonal wildflowers. In autumn, chum salmon return to spawn and draw eagles and visitors to the river; the park also has a visitor centre, picnic areas and camping.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '705', NULL),
    ('provincial-gordon-bay-park', 'Gordon Bay Park', 'provincial', 48.833373, -124.201395, 'South Island', 'On the shore of Lake Cowichan, Gordon Bay is a family camping destination with a sandy swimming beach and warm summer water. The surrounding lake and valley also draw anglers, boaters and visitors interested in the area''s local history.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '707', NULL),
    ('provincial-gowlland-tod-park', 'Gowlland Tod Park', 'provincial', 48.54069, -123.514313, 'South Island', 'This day-use park preserves much of the Gowlland Range and part of Tod Inlet, a large natural area near Greater Victoria. More than 25 kilometres of trails cross varied terrain and provide viewpoints for hiking, nature watching and picnics.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '708', NULL),
    ('provincial-hathayim-marine-park-a-k-a-von-donop-marine-park', 'Háthayim Marine Park', 'provincial', 50.17642, -124.960916, 'Discovery Islands', 'Also known as Von Donop Marine Park, Háthayim is a long, sheltered inlet on Cortes Island and a favored anchorage for boaters exploring the Discovery Islands. This undeveloped marine wilderness includes lakes, estuaries, a saltwater lagoon and old-growth forest, with wilderness camping permitted.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '728', NULL),
    ('provincial-helliwell-park', 'Helliwell Park', 'provincial', 49.500451, -124.600376, 'Northern Gulf Islands', 'A coastal trail follows the bluffs at St. John''s Point on Hornby Island, passing old-growth Douglas fir and Garry oak. The exposed headland looks across the Strait of Georgia to the Coast Mountains and offers chances to spot marine wildlife.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '742', NULL),
    ('provincial-hemer-park', 'Hemer Park', 'provincial', 49.099372, -123.831412, 'Central Island', 'Easy trails wind through mature forest beside Holden Lake and its marshes south of Nanaimo. A viewing platform overlooks the wetland, making this a popular place for bird watching and quiet walks.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '743', NULL),
    ('provincial-hesquiat-lake-park', 'Hesquiat Lake Park', 'provincial', 49.501556, -126.387362, 'Central Island', 'This remote wilderness park on Clayoquot Sound''s Hesquiat Lake is reached by boat or float plane. Mature forest surrounds the lake, where visitors can fish and observe nature; there are no developed facilities and few visitors.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '745', NULL),
    ('provincial-hesquiat-peninsula-park', 'Hesquiat Peninsula Park', 'provincial', 49.434424, -126.512731, 'Central Island', 'Hesquiat Peninsula protects a rugged stretch of the eastern shore of Nootka Sound and is known for coastal hiking, boating and sea kayaking. Nearby, Cougar Annie''s Garden reflects the history of a homesteading family on this remote coast.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '746', NULL),
    ('provincial-hitchie-creek-park', 'Hitchie Creek Park', 'provincial', 48.795521, -124.739988, 'South Island', 'Within the Nitinat Lake watershed, Hitchie Creek protects lowland old-growth rainforest and river and lake habitats. The creek corridor supports wildlife movement and a wide range of plants and animals.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '748', NULL),
    ('provincial-horne-lake-caves-park', 'Horne Lake Caves Park', 'provincial', 49.345175, -124.755373, 'Central Island', 'Horne Lake Caves protects an extensive underground limestone world, part of Vancouver Island''s remarkable cave network. The caves and their fragile mineral formations are the focus of the park, which was established to conserve them from damage.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '754', NULL),
    ('provincial-hwsalu-utsum-park', 'Hwsalu-Utsum Park', 'provincial', 48.654286, -123.7354, 'South Island', 'Near the Koksilah River in the Cowichan Valley, Hwsalu-Utsum protects pocket grasslands and old-growth forest that provide habitat for vulnerable wildlife. The province says Cowichan people have used this land since time immemorial and that it holds spiritual and cultural importance.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '5464', NULL),
    ('provincial-juan-de-fuca-park', 'Juan De Fuca Park', 'provincial', 48.436504, -124.09295, 'South Island', 'This west-coast park follows the Strait of Juan de Fuca, with surf, forest and marine wildlife along its rugged shore. The Juan de Fuca Marine Trail is the main draw, while China Beach and Botanical Beach offer additional coastal access.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '777', NULL),
    ('provincial-kennedy-lake-park', 'Kennedy Lake Park', 'provincial', 49.050445, -125.593933, 'Central Island', 'Two day-use sites on Kennedy Lake''s south shore provide access to swimming, kayaking, fishing and windsurfing. In autumn, visitors may see sockeye spawning along the beach, with black bears also active in the area.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '785', NULL),
    ('provincial-kennedy-river-bog-park', 'Kennedy River Bog Park', 'provincial', 49.101392, -125.627168, 'Central Island', 'This small day-use park protects a distinctive bog beside the Kennedy River on Vancouver Island''s west coast. Its wetland and surrounding trees attract ospreys, eagles, ducks and songbirds, making it a quiet spot for bird watching.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '786', NULL),
    ('provincial-kin-beach-park', 'Kin Beach Park', 'provincial', 49.727894, -124.897436, 'Central Island', 'Overlooking the Strait of Georgia in the Comox Valley, Kin Beach has a campground and a day-use area with picnic facilities and a playground. Visitors can explore the rocky shore or relax in the shade of mature Douglas fir.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '795', NULL),
    ('provincial-kitty-coleman-beach-park', 'Kitty Coleman Beach Park', 'provincial', 49.788488, -124.996026, 'North Island', 'This oceanfront park on the Strait of Georgia offers swimming, boating, fishing and shoreline camping. Its facilities include picnic areas, boat launches and nature trails, while the protected area includes mature forest and the Kitty Coleman Creek estuary.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '804', NULL),
    ('provincial-koksilah-river-park', 'Koksilah River Park', 'provincial', 48.635858, -123.743535, 'South Island', 'West of Shawnigan Lake, this undeveloped park follows the scenic Koksilah River and canyon. Visitors come for hiking, fishing, swimming and picnics beside the river.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '814', NULL),
    ('provincial-lawn-point-park', 'Lawn Point Park', 'provincial', 50.336879, -127.966904, 'North Island', 'Lawn Point lies on a remote stretch between Brooks Peninsula and Quatsino Sound, with a broad coastal bench unlike the area''s steep rocky shoreline. Kayakers use this undeveloped park as a wilderness camping stop, with open views along the coast.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '830', NULL),
    ('provincial-little-qualicum-falls-park', 'Little Qualicum Falls Park', 'provincial', 49.287317, -124.620756, 'Central Island', 'Waterfalls carve a rocky gorge along the Little Qualicum River, while the park also reaches the south shore of Cameron Lake. Forested trails, picnic areas, lake swimming and camping make it a popular stop in central Vancouver Island.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '836', NULL),
    ('provincial-loveland-bay-park', 'Loveland Bay Park', 'provincial', 50.049299, -125.450242, 'North Island', 'This quiet, rustic campground near Campbell River sits beside Campbell Lake and has a boat launch. Visitors can swim, fish or relax by the water, or use the park as a base for exploring nearby North Island communities and islands.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '840', NULL),
    ('provincial-lower-nimpkish-park', 'Lower Nimpkish Park', 'provincial', 50.536738, -127.009362, 'North Island', 'A long undeveloped strip of parkland protects both banks of the Lower Nimpkish River near the north end of Nimpkish Lake. The river corridor supports fishing and nature viewing, and safeguards riparian habitat used by nesting eagles and threatened marbled murrelets.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '842', NULL),
    ('provincial-lower-tsitika-river-park', 'Lower Tsitika River Park', 'provincial', 50.460456, -126.591938, 'North Island', 'This park protects upland parts of the Tsitika watershed beside the Robson Bight orca habitat. It is lightly visited, and entry to the Tsitika River estuary is prohibited; the protected landscape spans low-elevation forest through alpine tundra.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '4845', NULL),
    ('provincial-macmillan-park', 'Macmillan Park', 'provincial', 49.279996, -124.66686, 'Central Island', 'MacMillan Park protects an internationally significant old-growth Douglas-fir forest. Cathedral Grove is its best-known area, with an accessible stand of giant trees and forest paths that make the landscape easy to experience on foot.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '846', NULL),
    ('provincial-main-lake-park', 'Main Lake Park', 'provincial', 50.209763, -125.215043, 'Discovery Islands', 'On Quadra Island, Main Lake Park protects a chain of six lakes and a diverse freshwater ecosystem. Canoeing, kayaking and wilderness camping are among the ways to explore its waterways, forest and abundant bird and wildlife habitat.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '848', NULL),
    ('provincial-mansons-landing-park', 'Mansons Landing Park', 'provincial', 50.066981, -124.982745, 'Discovery Islands', 'This Cortes Island park fronts both Hague Lake and Manson Bay. Visitors can swim in the lake and watch marine life in Mansons Lagoon; camping is available at nearby Smelt Bay Park rather than within this park.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '849', NULL),
    ('provincial-marble-river-park', 'Marble River Park', 'provincial', 50.544121, -127.524645, 'North Island', 'A 4.2-kilometre trail along the Marble River supports hiking, biking and access to salmon viewing points. The river is also a destination for freshwater and tidal angling, especially during seasonal fish runs.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '856', NULL),
    ('provincial-memory-island-park', 'Memory Island Park', 'provincial', 48.611029, -123.632973, 'South Island', 'This tiny day-use island in Shawnigan Lake offers a quiet place to picnic and observe nature. It is accessible by boat, canoe or kayak and provides habitat for birds, small mammals, amphibians and other species.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '865', NULL),
    ('provincial-miracle-beach-park', 'Miracle Beach Park', 'provincial', 49.8468, -125.096564, 'North Island', 'A broad sandy beach is the centrepiece of this popular family destination in the Comox Valley. Forest trails, picnic areas, a playground, showers, vehicle-accessible campsites and group camping make it an easy place to spend a full day or overnight.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '869', NULL),
    ('provincial-mitlenatch-island-nature-park', 'Mitlenatch Island Nature Park', 'provincial', 49.950402, -125.004015, 'Discovery Islands', 'Mitlenatch is home to the Strait of Georgia''s largest seabird colony, with thousands of nesting gulls, cormorants, guillemots and other birds. The protected marine area also safeguards intertidal and underwater life around the island.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '871', NULL),
    ('provincial-montague-harbour-marine-park', 'Montague Harbour Marine Park', 'provincial', 48.898784, -123.405068, 'Gulf Islands', 'On Galiano Island, this park combines sheltered harbour, beaches, tidal lagoons, meadows and forest. Boaters can moor in the harbour, while visitors arriving by ferry can use the vehicle and walk-in campsites and explore the shoreline.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '877', NULL),
    ('provincial-morden-colliery-historic-park', 'Morden Colliery Historic Park', 'provincial', 49.094992, -123.87328, 'Central Island', 'This small day-use park preserves the last remaining coal tipple on Vancouver Island, a concrete industrial structure built for the Morden coal mine in the early 1900s. It offers a direct connection to the island''s coal-mining history.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '882', NULL),
    ('provincial-morton-lake-park', 'Morton Lake Park', 'provincial', 50.124386, -125.47872, 'North Island', 'Morton Lake is a destination for trout fishing, swimming, canoeing and boating in the Campbell River lake district. A sandy beach provides a place to relax, and the park also offers camping among the surrounding forest.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '885', NULL),
    ('provincial-mount-erskine-park', 'Mount Erskine Park', 'provincial', 48.848864, -123.548951, 'Gulf Islands', 'Mount Erskine on Salt Spring Island combines coastal Douglas-fir forest, mossy rock outcrops, Garry oak habitat and open bluffs. Hiking trails climb toward the summit, where visitors find broad island views.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '5234', NULL),
    ('provincial-mount-geoffrey-escarpment-park', 'Mount Geoffrey Escarpment Park', 'provincial', 49.506061, -124.682406, 'Northern Gulf Islands', 'A trail network on Hornby Island crosses the Mount Geoffrey escarpment and opens onto striking coastal views. Hiking and mountain biking are popular, with care needed to stay on trails and protect the islands'' dry, sensitive ecosystems.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '5135', NULL),
    ('provincial-mount-maxwell-park', 'Mount Maxwell Park', 'provincial', 48.803711, -123.51468, 'Gulf Islands', 'Baynes Peak, one of Salt Spring Island''s highest points, is the centre of this day-use park and its expansive Gulf Island views. Trails also pass old-growth Douglas fir, Garry oak meadows and salmon-bearing creeks near the island''s largest undeveloped estuary.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '895', NULL),
    ('provincial-muqqiwn-brooks-peninsula-park', 'Muqqiwn/Brooks Peninsula Park', 'provincial', 50.179858, -127.673648, 'North Island', 'This remote park protects Brooks Peninsula on northwestern Vancouver Island, a storm-exposed headland with rugged coastline and pockets of shelter. Its dual name recognizes the Che:k''tles7et''h'' connection to this distinctive wilderness landscape.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '530', NULL),
    ('provincial-nimpkish-lake-park', 'Nimpkish Lake Park', 'provincial', 50.337771, -127.004668, 'North Island', 'A rugged wilderness area at the south end of Nimpkish Lake, this park protects old-growth forest in the Tlakwa Creek watershed. Remote recreation includes nature viewing, backcountry skiing, mountaineering and wilderness camping.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '924', NULL),
    ('provincial-nismaakqin-park', 'Nism̓aakqin Park', 'provincial', 49.387813, -126.334488, 'Central Island', 'Known for mux̣ʷšiƛa, or Hot Springs Cove, this remote Clayoquot Sound park features mineral springs that cascade down a waterfall into a sequence of six rocky pools. Ocean water cools the pools as it moves through them.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '850', NULL),
    ('provincial-nitinat-river-park', 'Nitinat River Park', 'provincial', 48.898138, -124.557968, 'South Island', 'The Nitinat River flows through lush forest and supports salmon and wildlife, with deep significance to local Indigenous communities. This wilderness park protects rare plants but has no developed day-use or camping facilities.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '930', NULL),
    ('provincial-nuchatlitz-park', 'Nuchatlitz Park', 'provincial', 49.808266, -126.970654, 'North Island', 'At the northwestern tip of Nootka Island, Nuchatlitz includes many small island groups and quiet channels. Paddlers can explore by kayak and camp along the coast, with opportunities for boating, fishing and wildlife viewing.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '938', NULL),
    ('provincial-octopus-islands-marine-park', 'Octopus Islands Marine Park', 'provincial', 50.267942, -125.23253, 'Discovery Islands', 'A group of small islands provides sheltered anchorages along the Inside Passage, making this a favourite marine stop for boaters and paddlers. Visitors also come to swim, hike, fish, dive, camp and connect with a rough portage route across Quadra Island.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '941', NULL),
    ('provincial-petroglyph-park', 'Petroglyph Park', 'provincial', 49.140646, -123.926178, 'Central Island', 'At the south end of Nanaimo, this small park protects a notable concentration of ancient rock carvings created by First Nations peoples. The petroglyphs offer a window into cultural history more than a thousand years old.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '962', NULL),
    ('provincial-pirates-cove-marine-park', 'Pirates Cove Marine Park', 'provincial', 49.095897, -123.725946, 'Gulf Islands', 'This sheltered marine park on De Courcy Island is a popular anchorage south of Nanaimo. Kayaking, camping, swimming, hiking, picnicking and shoreline exploration offer ways to experience its quiet coves and wildlife.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '967', NULL),
    ('provincial-quatsino-park', 'Quatsino Park', 'provincial', 50.49486, -127.820415, 'North Island', 'Quatsino Park protects rugged coastline and large old-growth trees beside Quatsino Sound. It is a scenic stop on a popular sea-kayaking route, with an inland wilderness lake adding more room to explore.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '989', NULL),
    ('provincial-raft-cove-park', 'Raft Cove Park', 'provincial', 50.584383, -128.236155, 'North Island', 'A long crescent beach at the Macjack River mouth defines this remote park on northwestern Vancouver Island. Day hikers and backpackers visit for its sandy shore, coastal headlands and exposed wilderness setting; bring warm clothing and rain gear.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '991', NULL),
    ('provincial-rathtrevor-beach-park', 'Rathtrevor Beach Park', 'provincial', 49.32257, -124.26199, 'Central Island', 'Parksville''s wide sandy shore, old-growth woodland and ocean sunsets make Rathtrevor a popular Vancouver Island destination. Campsites sit among the trees, with an expansive beach revealed at low tide.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '994', NULL),
    ('provincial-read-island-park', 'Read Island Park', 'provincial', 50.144456, -125.132297, 'Discovery Islands', 'Read Island protects a mix of old and second-growth forest, bog and lowland habitat, including nesting areas for bald eagles. The varied landscape supports wildlife from deer and otters to seals and sea lions.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '995', NULL),
    ('provincial-rebecca-spit-marine-park', 'Rebecca Spit Marine Park', 'provincial', 50.100865, -125.189859, 'Discovery Islands', 'A narrow sandy spit on Quadra Island has beaches on both sides and views over sheltered Drew Harbour. Walking trails, picnic areas, swimming, kayaking and fishing make it a popular day-use park.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '997', NULL),
    ('provincial-roberts-memorial-park', 'Roberts Memorial Park', 'provincial', 49.062325, -123.774383, 'Central Island', 'A short forest trail leads to a rocky beach on Stewart Channel near Nanaimo. The park''s distinctive sandstone ledges preserve a record of ancient seabeds and provide haul-out places for sea lions.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1002', NULL),
    ('provincial-rock-bay-marine-park', 'Rock Bay Marine Park', 'provincial', 50.334033, -125.456594, 'North Island', 'This foreshore-only park sits where Discovery Passage meets Johnstone Strait and serves boaters exploring the area. Otter Cove provides sheltered anchorage, while nearby land access and operations are private.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1008', NULL),
    ('provincial-rosewall-creek-park', 'Rosewall Creek Park', 'provincial', 49.453404, -124.781869, 'Central Island', 'A small day-use park follows Rosewall Creek through conifers and broadleaf maple south of Fanny Bay. Two picnic areas and a short riverside path make it a quiet place to watch the creek, especially in autumn.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1016', NULL),
    ('provincial-ruckle-park', 'Ruckle Park', 'provincial', 48.780917, -123.388751, 'Gulf Islands', 'Seven kilometres of rocky shoreline, coves and bays make Ruckle a rewarding place to explore Salt Spring Island''s coast. Forest, fields and shore support abundant wildlife, while campsites overlook Swanson Channel and working farmland preserves local history.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1019', NULL),
    ('provincial-rugged-point-marine-park', 'Rugged Point Marine Park', 'provincial', 49.962827, -127.242195, 'North Island', 'Accessible only by boat, Rugged Point is a coastal stop on northern Vancouver Island''s west side. Sheltered beaches on the peninsula''s north contrast with surf-exposed outer shores, with safe anchorages for boaters in suitable conditions.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1020', NULL),
    ('provincial-sandwell-park', 'Sandwell Park', 'provincial', 49.186401, -123.816833, 'Gulf Islands', 'A short wooded walk on Gabriola Island ends at a picnic area above a sandy beach with views across the Strait of Georgia. At low tide, visitors can reach a sandstone petroglyph east of the day-use area.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1026', NULL),
    ('provincial-santa-gertrudis-boca-del-infierno-park', 'Santa Gertrudis-Boca Del Infierno Park', 'provincial', 49.610888, -126.627934, 'Central Island', 'This boat-access park in Nootka Sound supports kayaking, boating, wilderness camping, fishing and wildlife viewing. Sheltered anchorages at Boca del Infierno Bay and Santa Gertrudis Cove lie within a landscape shaped by Indigenous history and coastal travel.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1028', NULL),
    ('provincial-saysutshun-newcastle-island-marine-park', 'Saysutshun (Newcastle Island Marine) Park', 'provincial', 49.188512, -123.933753, 'Gulf Islands', 'A short passenger-ferry ride from Nanaimo reaches Saysutshun, an island park with steep sandstone shores and a long history of cultural and recreational use. Visitors can explore its paths and beaches, camp, and learn about the island''s stories.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '921', NULL),
    ('provincial-schoen-lake-park', 'Schoen Lake Park', 'provincial', 50.176607, -126.245375, 'North Island', 'Northwest of Campbell River, Schoen Lake pairs a quiet lake with surrounding mountain wilderness. Hiking, backpacking, boating, fishing, swimming and camping are possible, with a more primitive setting than developed destination parks.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1034', NULL),
    ('provincial-small-inlet-marine-park', 'Small Inlet Marine Park', 'provincial', 50.255539, -125.284259, 'Discovery Islands', 'At Quadra Island''s north end, Small Inlet offers a protected anchorage near tidal rapids and a route to Newton Lake. A rough trail reaches the lake, and a longer portage links the park to Waiatt Bay in Octopus Islands Marine Park.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1097', NULL),
    ('provincial-smelt-bay-park', 'Smelt Bay Park', 'provincial', 50.031574, -124.993326, 'Discovery Islands', 'At the south end of Cortes Island, Smelt Bay is named for capelin that spawn along the shore in early autumn. Its beach is suited to low-tide marine exploration, with camping and views along the bay toward Sutil Point.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1098', NULL),
    ('provincial-sooke-mountain-park', 'Sooke Mountain Park', 'provincial', 48.438764, -123.657325, 'South Island', 'Established near Victoria to protect wilderness, wildlife and scenic values, Sooke Mountain preserves rugged hills, lakes, forest slopes and watershed. Visitors can hike, cycle, ride horses, fish and watch wildlife in this part of the Sooke Hills greenbelt.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1103', NULL),
    ('provincial-sooke-potholes-park', 'Sooke Potholes Park', 'provincial', 48.428675, -123.711595, 'South Island', 'The Sooke River has carved deep, smooth rock pools beside this popular day-use area. The potholes formed through glacial action and swirling stones during the last ice age, creating distinctive swimming holes and river scenery.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1104', NULL),
    ('provincial-spectacle-lake-park', 'Spectacle Lake Park', 'provincial', 48.578882, -123.570243, 'South Island', 'Mature forest, wetlands and a spring-fed lake create a compact nature area northwest of Victoria. Visitors can swim, fish, walk a trail that circles the lake, and in winter sometimes skate when conditions allow.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1110', NULL),
    ('provincial-spider-lake-park', 'Spider Lake Park', 'provincial', 49.34349, -124.633304, 'Central Island', 'Warm water and a small sandy beach make Spider Lake a popular place for swimming and picnics. Canoeists and kayakers can follow the shoreline into quieter bays west of Qualicum Beach.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1111', NULL),
    ('provincial-sproat-lake-park', 'Sproat Lake Park', 'provincial', 49.292417, -124.92751, 'Central Island', 'Sproat Lake draws visitors for swimming, fishing, water skiing and windsurfing in the Alberni Valley. Short paths reach the shore and the K’ak’awin petroglyph panel, an important prehistoric carving site beside the lake.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1112', NULL),
    ('provincial-squitty-bay-park', 'Squitty Bay Park', 'provincial', 49.449242, -124.17059, 'Northern Gulf Islands', 'A small protected bay on Lasqueti Island is enclosed by rocky headlands and dry terrain. Visitors can picnic, walk out onto the point and take in distant views of Mount Baker and the Comox Glacier.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1113', NULL),
    ('provincial-stamp-river-park', 'Stamp River Park', 'provincial', 49.342581, -124.930369, 'Central Island', 'Trails follow the Stamp River through forest and rapids to waterfalls and viewing points. Thousands of salmon gather below Stamp Falls each year before climbing the fish ladders, making the seasonal run a highlight for visitors.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1116', NULL),
    ('provincial-strathcona-park', 'Strathcona Park', 'provincial', 49.592258, -125.690236, 'Central Island', 'Established in 1911, Strathcona is British Columbia''s oldest park and a vast mountain wilderness near the centre of Vancouver Island. Snowy peaks, alpine plateaus, lakes, waterfalls and forest draw hikers and campers through the warmer months and backcountry skiers in winter.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1125', NULL),
    ('provincial-strathcona-westmin-park', 'Strathcona - Westmin Park', 'provincial', 49.574561, -125.592441, 'Central Island', 'This unusual park encloses the active Myra Falls mine within the wider Strathcona wilderness. Away from the industrial site, its rugged forest setting offers hiking and backcountry camping opportunities.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1127', NULL),
    ('provincial-sulphur-passage-park', 'Sulphur Passage Park', 'provincial', 49.412437, -126.094873, 'Central Island', 'This undeveloped wilderness park in Clayoquot Sound includes a fjord, estuary and old-growth Sitka spruce forest. Its remote shore and productive marine habitat support wildlife viewing, including whales and other marine mammals.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1134', NULL),
    ('provincial-surge-narrows-park', 'Surge Narrows Park', 'provincial', 50.232039, -125.146651, 'Discovery Islands', 'Strong tidal currents converge near Maurelle Island to create the rapids that give Surge Narrows its name. The changing water supports abundant marine life, including sea stars, anemones, urchins and sea cucumbers.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1140', NULL),
    ('provincial-sydney-inlet-park', 'Sydney Inlet Park', 'provincial', 49.48009, -126.283079, 'Central Island', 'Sydney Inlet protects a striking fjord in northern Clayoquot Sound, with old-growth Sitka spruce and Douglas fir, the Sydney River and its estuary. Boaters and sea kayakers use the sheltered inlet to explore the remote west coast.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1145', NULL),
    ('provincial-tahsish-kwois-park', 'Tahsish-Kwois Park', 'provincial', 50.189694, -127.161658, 'North Island', 'A rugged, isolated park in Kyuquot Sound protects old-growth forest, two lakes, a river canyon and broad valleys. The Tahsish River Ecological Reserve is surrounded by the park, adding to the area''s value as a large connected wilderness landscape.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1149', NULL),
    ('provincial-taylor-arm-park', 'Taylor Arm Park', 'provincial', 49.276598, -125.043888, 'Central Island', 'Taylor Arm provides group camping close to Sproat Lake, with a trail and highway underpass connecting campers to the water. Wooded grounds, undeveloped beaches and two day-use areas make it useful for lakeside outings.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1159', NULL),
    ('provincial-thurston-bay-marine-park', 'Thurston Bay Marine Park', 'provincial', 50.353893, -125.321806, 'Discovery Islands', 'Boat access reaches two sections of this marine park on Sonora Island beside Johnstone Strait. Sheltered anchorages, small beaches, paddling, fishing and hiking make it a useful Inside Passage stop; rustic camping is allowed, but facilities are undeveloped.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1170', NULL),
    ('provincial-tranquil-creek-park', 'Tranquil Creek Park', 'provincial', 49.315691, -125.620982, 'Central Island', 'Around Paradise Lake, steep forested slopes rise to alpine meadows at the head of Tranquil Creek. This remote wilderness has no trails and is reached by float plane, offering rustic hiking and camping for experienced visitors.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1175', NULL),
    ('provincial-tribune-bay-park', 'Tribune Bay Park', 'provincial', 49.527889, -124.639341, 'Northern Gulf Islands', 'Hornby Island''s long white-sand beach slopes into the warm waters of the Strait of Georgia and is lined by distinctive rock formations. A frontcountry campground beside the bay adds campsites, cabins and a playground near the popular swimming shore.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1178', NULL),
    ('provincial-vargas-island-park', 'Vargas Island Park', 'provincial', 49.174549, -126.031166, 'West Coast Islands', 'Near Tofino, Vargas Island is a popular destination for paddling, wilderness camping and wildlife watching, including gray whales around Ahous Bay. The park protects rugged coastline, offshore islets and interior bogs in Clayoquot Sound.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1201', NULL),
    ('provincial-wakes-cove-park', 'Wakes Cove Park', 'provincial', 49.122943, -123.701825, 'Gulf Islands', 'Wakes Cove offers a sheltered anchorage in the central Gulf Islands, along with rustic walking trails, picnic spots and wildlife viewing. Camping is not allowed, and visitors need to stay within park boundaries beside neighboring private land.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '5003', NULL),
    ('provincial-wallace-island-marine-park', 'Wallace Island Marine Park', 'provincial', 48.942472, -123.551581, 'Gulf Islands', 'Between Salt Spring and Galiano islands, Wallace Island''s beaches, coves and offshore islets create sheltered paddling routes. Boaters and kayakers visit for day trips or overnight camping, with eagles, deer, mink and harbour seals among the wildlife.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1207', NULL),
    ('provincial-west-shawnigan-lake-park', 'West Shawnigan Lake Park', 'provincial', 48.641467, -123.650828, 'South Island', 'A small day-use park on Shawnigan Lake protects Douglas-fir forest and provides beach access for swimming and paddling. Picnic tables, toilets and short walking paths support relaxed summer visits.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1216', NULL),
    ('provincial-weymer-creek-park', 'Weymer Creek Park', 'provincial', 49.882751, -126.61557, 'North Island', 'Weymer Creek protects an extensive karst landscape and cave system near Tahsis, including habitat for the red-listed Keen''s long-eared myotis bat. Caves are ecologically sensitive, and BC Parks cautions against caving until a management plan is complete.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1218', NULL),
    ('provincial-white-ridge-park', 'White Ridge Park', 'provincial', 49.777527, -125.973322, 'North Island', 'White Ridge rises behind Gold River and protects internationally notable white limestone karst, caves and wildlife habitat. Its underground features are sensitive, so BC Parks advises against caving until a management plan is complete.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1224', NULL),
    ('provincial-white-river-park', 'White River Park', 'provincial', 50.140436, -126.033107, 'North Island', 'This small wilderness park protects old-growth forest and habitat for Roosevelt elk and black bears beside the White River. A short loop trail descends through large Douglas fir and red cedar to the water.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1225', NULL),
    ('provincial-wood-mountain-ski-park', 'Wood Mountain Ski Park', 'provincial', 49.658012, -125.164887, 'Central Island', 'North of Comox Lake and west of Courtenay, Wood Mountain Ski Park is a roughly 240-acre park established in 1966. The provincial geographical names record says it was named for Clinton S. Wood and designated for recreation and wildlife preservation.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1232', NULL),
    ('provincial-woss-lake-park', 'Woss Lake Park', 'provincial', 50.060856, -126.626665, 'North Island', 'South of Woss on northern Vancouver Island, this undeveloped park protects part of Woss Lake and the steep forested slopes and snowfields of Rugged Mountain. Its remote lake and mountain setting offers a wilderness experience.', 'https://catalogue.data.gov.bc.ca/dataset/parks-ecological-reserves-and-protected-areas', 'BC Parks / DataBC — TANTALIS protected areas', '1234', NULL),
    ('regional-albert-head-lagoon-regional-park', 'Albert Head Lagoon Regional Park', 'regional', 48.39516, -123.490868, 'Capital Region', 'A sheltered lagoon and dune landscape ends at a cobble beach with views toward the Olympic Mountains. It is a compact stop for shoreline walks, birdwatching and a picnic.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-ayum-creek-regional-park', 'Ayum Creek Regional Park', 'regional', 48.391627, -123.66096, 'Capital Region', 'Forest and wetland surround the estuary where Ayum Creek reaches Sooke Basin. The creek is important habitat for salmon and trout; the park has no public facilities.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-beachcomber-regional-park', 'Beachcomber Regional Park', 'regional', 49.313002, -124.213611, 'Central Island', 'At the end of Nanoose’s Beachcomber Peninsula, this small oceanfront park pairs short woodland trails with rocky shoreline and tidal pools. Views reach across Craig Bay toward Parksville and Mount Arrowsmith, and across the Strait of Georgia to the mainland mountains.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-bear-hill-regional-park', 'Bear Hill Regional Park', 'regional', 48.545162, -123.40296, 'Capital Region', 'Woodland trails climb a hilly landscape of Douglas-fir, Garry oak and arbutus to a summit with views across the Saanich Peninsula toward Mount Baker and nearby islands. Spring brings wildflowers, and some routes are used by horseback riders.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-benson-creek-falls-regional-park', 'Benson Creek Falls Regional Park', 'regional', 49.192284, -124.079726, 'Central Island', 'This rugged, forested park follows creeks through steep ravines to waterfalls, including Ammonite Falls. The falls are reached by a rough hike of about 1.5 kilometres from Weigles Road or 2.5 kilometres from Creekside Place.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-bere-point-regional-park', 'Bere Point Regional Park', 'regional', 50.670833, -127.056667, 'Northern Islands', 'Six kilometres from Sointula, this wooded coastal campground sits close to the beach with views across Queen Charlotte Strait to the coastal mountains. A whale-watching platform overlooks the shore, and the Beautiful Bay Trail begins in the park.', 'https://www.rdmw.bc.ca/recreation-leisure/camping-information/bere-point/', 'Regional District of Mount Waddington + BC Geographical Names Office', 'bcgnis-22727', NULL),
    ('regional-brooks-point-regional-park', 'Brooks Point Regional Park', 'regional', 48.735746, -123.187155, 'Gulf Islands', 'On South Pender Island, trails cross coastal forest, meadow and a wetland boardwalk to rocky bluffs and beaches. Look across Boundary Pass toward the San Juan Islands and Mount Baker, and watch for spring chocolate lilies in the meadow.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-coats-marsh-regional-park', 'Coats Marsh Regional Park', 'regional', 49.154187, -123.814594, 'Gulf Islands', 'Wetlands and second-growth forest form Gabriola Island’s first protected wetland area. Rough trails offer a close look at the marsh and its birdlife.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-coles-bay-regional-park', 'Coles Bay Regional Park', 'regional', 48.631507, -123.465039, 'Capital Region', 'Short woodland trails lead to a pebble beach on Saanich Inlet. The sheltered shoreline is a popular summer swimming spot, with picnic tables and accessible toilets near the parking area.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-descanso-bay-regional-park', 'Descanso Bay Regional Park', 'regional', 49.182833, -123.858906, 'Gulf Islands', 'This oceanfront Gabriola park is a short distance from the ferry and village centre. Its wooded campground, small boat launch, shoreline coves and picnic area make it a base for kayaking, swimming and exploring the island.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-devonian-regional-park', 'Devonian Regional Park', 'regional', 48.364253, -123.537749, 'Capital Region', 'This small coastal conservation area has a wooded trail beside Sherwood Creek leading to a cobble beach. The shore opens to views of Juan de Fuca Strait, Race Rocks and the Olympic Mountains; Sherwood Pond is a birdwatching stop.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-east-point-regional-park', 'East Point Regional Park', 'regional', 48.782449, -123.047104, 'Gulf Islands', 'At Saturna Island’s eastern tip, coastal bluffs look toward the San Juan Islands and Washington mainland. The park connects with Gulf Islands National Park Reserve and is known for its open shoreline scenery.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-east-sooke-regional-park', 'East Sooke Regional Park', 'regional', 48.339419, -123.669949, 'Capital Region', 'A network of roughly 50 kilometres of trails crosses forest, marsh, open fields and rugged coast. The 10-kilometre Coast Trail links pocket beaches and rocky bays, with views across Juan de Fuca Strait to the Olympic Mountains.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-elk-beaver-lake-regional-park', 'Elk/Beaver Lake Regional Park', 'regional', 48.52232, -123.395954, 'Capital Region', 'Elk and Beaver Lakes have four beaches, picnic areas and about 15 kilometres of walking routes, including a 10-kilometre loop. Designated trails allow cycling and horseback riding, and Elk Lake has an accessible fishing dock and stocked rainbow trout.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-englishman-river-regional-park', 'Englishman River Regional Park', 'regional', 49.287303, -124.286889, 'Central Island', 'A broad river corridor protects salmon habitat, including a constructed side channel and community hatchery. The park’s open trails welcome walkers, cyclists and horseback riders, with wildlife such as elk and bears in the surrounding landscape.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-francis-king-regional-park', 'Francis/King Regional Park', 'regional', 48.484037, -123.448166, 'Capital Region', 'This forested conservation area pairs the universally accessible Elsie King Trail with a grove of old Douglas-fir trees. Additional trails connect to Thetis Lake Regional Park for a longer walk.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-george-hill-regional-park', 'George Hill Regional Park', 'regional', 48.815866, -123.312337, 'Capital Region', 'A steep forest trail on North Pender climbs to a broad viewpoint over Galiano, Mayne and Salt Spring islands. On clear days the Olympic Mountains are visible; the official trail starts from Ogden Road or Upper Terrace Road.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-gonzales-hill-regional-park', 'Gonzales Hill Regional Park', 'regional', 48.413732, -123.324787, 'Capital Region', 'Rocky knolls and Garry oak meadows lead to the 66-metre summit, where views span Victoria and the Sooke Hills. The historic Gonzales Observatory and spring wildflowers add interest to a short hilltop visit.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-hamilton-marsh-regional-park-and-conservation-area', 'Hamilton Marsh Regional Park and Conservation Area', 'regional', 49.314008, -124.465592, 'Central Island', 'This 364-hectare property protects mature forest and a 36-hectare wetland within the French Creek watershed. Its marsh and surrounding forest are the defining features of this newly protected conservation area.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-horne-lake-regional-park', 'Horne Lake Regional Park', 'regional', 49.343037, -124.742473, 'Central Island', 'Set below Mount Mark beside Horne Lake, this campground offers forest sites, canoe and stand-up paddleboard rentals, fishing and picnic space. It sits beside Horne Lake Caves Provincial Park and its cave tours.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-horth-hill-regional-park', 'Horth Hill Regional Park', 'regional', 48.684372, -123.433748, 'Capital Region', 'Wooded slopes at the north end of the Saanich Peninsula lead to viewpoints over Satellite Channel, the peninsula and the Gulf Islands. The park covers about 36 hectares.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-island-view-beach-regional-park', 'Island View Beach Regional Park', 'regional', 48.578208, -123.372294, 'Capital Region', 'A long sandy shoreline on the eastern Saanich Peninsula sits beside dunes, wetlands and coastal shrubs. Visitors come to walk, picnic and swim, while the beach and wetlands provide habitat for resident and migrating birds.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-jordan-river-regional-park', 'Jordan River Regional Park', 'regional', 48.420658, -124.032081, 'Capital Region', 'A forest trail and stairway descend from the coastal park to Sandcut Beach, a long cobble shore on Juan de Fuca Strait. The route opens to views toward the Olympic Peninsula.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-kapoor-regional-park', 'Kapoor Regional Park', 'regional', 48.490849, -123.714958, 'Capital Region', 'Following the Sooke River near the end of the Galloping Goose Regional Trail, Kapoor offers a quiet stretch of riverfront along old roads and trails. The park borders the historic Leechtown gold-rush site and former railway logging area.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-kwaksistah-regional-park', 'Kwaksistah Regional Park', 'regional', 50.521979, -128.027444, 'North Island', 'This remote, free campground at Winter Harbour has eight first-come sites, picnic tables, fire pits and outhouses, with no water, power or sewer service. The approach follows an active logging road, so allow extra time and be prepared to yield to logging trucks.', 'https://www.rdmw.bc.ca/recreation-leisure/camping-information/kwaksistah-regional-park/', 'Regional District of Mount Waddington + OpenStreetMap contributors', 'W827164115', NULL),
    ('regional-little-huson-cave-regional-park', 'Little Huson Cave Regional Park', 'regional', 50.28532, -126.950779, 'North Island', 'A short forest path leads from the parking area to limestone arches, rock bridges and clear pools along Atluck Creek. The caves and karst formations are the main draw; water levels vary with rainfall and snowmelt.', 'https://www.rdmw.bc.ca/media/Huson%20Cave%20Park%20Overview%281%29.pdf', 'Regional District of Mount Waddington + OpenStreetMap contributors', 'W816998556', NULL),
    ('regional-little-qualicum-river-estuary-regional-conservation-area', 'Little Qualicum River Estuary Regional Conservation Area', 'regional', 49.366442, -124.496404, 'Central Island', 'This coastal sand spit at the mouth of the Little Qualicum River supports marine life and waterfowl. Access to the spit is restricted for conservation; the adjacent wildlife management area offers a place to observe the estuary.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-little-qualicum-river-regional-park', 'Little Qualicum River Regional Park', 'regional', 49.32478, -124.548908, 'Central Island', 'This 111-hectare park follows both banks of the Little Qualicum River below Little Qualicum Falls. Rough trails lead to the river, while a developed route from Meadowood Way links with the provincial falls park.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-lone-tree-hill-regional-park', 'Lone Tree Hill Regional Park', 'regional', 48.51953, -123.514555, 'Capital Region', 'A rocky climb reaches the 364-metre summit of Lone Tree Hill, with views of the Malahat, Highlands, Victoria and the Olympic Mountains. The park is named for a small, bonsai-like Douglas-fir once recognized as a heritage tree.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-matheson-lake-regional-park', 'Matheson Lake Regional Park', 'regional', 48.362443, -123.60016, 'Capital Region', 'A loop trail circles the lake through a landscape of sensitive ecosystems, with a sandy beach for swimming and picnics in summer. The park connects with Roche Cove Regional Park and the Galloping Goose Regional Trail.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-matthews-point-regional-park', 'Matthews Point Regional Park', 'regional', 48.863899, -123.32888, 'Capital Region', 'Woodland paths and coastal bluffs open onto views of Active Pass. The park protects shoreline ecosystems on Salt Spring Island and offers opportunities for hiking, birdwatching and horseback riding.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-mill-farm-regional-park', 'Mill Farm Regional Park', 'regional', 48.772312, -123.520294, 'Capital Region', 'On Salt Spring Island, forest trails pass a remnant waterwheel from an early logging operation and one of the Gulf Islands’ larger old-growth stands. Openings in the forest look toward Saanich Inlet and Cowichan Bay, and rare plants include the phantom orchid.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-mill-hill-regional-park', 'Mill Hill Regional Park', 'regional', 48.458273, -123.478383, 'Capital Region', 'Trails climb through Douglas-fir forest and Garry oak habitat to a rocky 203-metre summit. From the top, look over Esquimalt Harbour and the Victoria area.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-moorecroft-regional-park', 'Moorecroft Regional Park', 'regional', 49.303921, -124.180612, 'Central Island', 'This oceanfront park protects Garry oak meadows and coastal Douglas-fir habitat under a conservation covenant. Low-impact trails and picnic spots bring visitors to the shoreline, with views across the Salish Sea to the coastal mountains.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-mount-arrowsmith-massif-regional-park', 'Mount Arrowsmith Massif Regional Park', 'regional', 49.221214, -124.576717, 'Central Island', 'A high alpine park spanning Mount Arrowsmith and Mount Cokely, with flower-filled meadows in late spring and summer. Long-standing routes lead onto the ridges and are best suited to experienced hikers; the RDN recommends guided hikes for novices.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-mount-arrowsmith-regional-park-acrd', 'Mount Arrowsmith Regional Park (ACRD)', 'regional', 49.249953, -124.596061, 'Central Island', 'The northern Mount Cokely slope is reached by gravel logging roads and offers alpine hiking routes via Rousseau Trail, Arrowsmith Trail and the Lower Ski Area Trail. Access roads cross private forest land, so check Mosaic’s designated public access openings before setting out.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-mount-benson-regional-park', 'Mount Benson Regional Park', 'regional', 49.153826, -124.037915, 'Central Island', 'Forested slopes above Nanaimo open to views of the city and Strait of Georgia, while the park protects headwaters feeding nearby lakes and rivers. The approach from the parking lot is steep and rough in places; allow three to five hours for the return hike and prepare for changing weather.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-mount-cain-alpine-park', 'Mount Cain Alpine Park', 'regional', 50.222771, -126.345699, 'North Island', 'A community-operated ski area in the North Island mountains, Mount Cain is known for deep powder and backcountry terrain. Winter conditions and access change with weather, so check current local updates before travelling.', 'https://www.rdmw.bc.ca/recreation-leisure/', 'Regional District of Mount Waddington + OpenStreetMap contributors', 'W579980733', NULL),
    ('regional-mount-parke-regional-park', 'Mount Parke Regional Park', 'regional', 48.839428, -123.286546, 'Gulf Islands', 'A winding woodland trail on Mayne Island passes western red cedar, red alder and lush fern understory before reaching viewpoints. Spring wildflowers and birds of prey are among the seasonal highlights.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-mount-wells-regional-park', 'Mount Wells Regional Park', 'regional', 48.437335, -123.552788, 'Capital Region', 'This Sooke Hills wilderness park combines second-growth forest with fragile mossy rock outcrops and spring wildflowers. Viewpoints look toward Juan de Fuca Strait, Victoria and the Sea to Sea greenbelt.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-mount-work-regional-park', 'Mount Work Regional Park', 'regional', 48.531032, -123.477666, 'Capital Region', 'Three freshwater lakes, Killarney, Durrance and Pease, anchor a broad network of recreation trails. Visitors can walk or swim at the lakes; canoeing and fishing are available at Durrance and Pease, with rainbow trout stocked at Durrance.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-mountain-forest-regional-park', 'Mountain Forest Regional Park', 'regional', 48.50589, -123.428139, 'Capital Region', 'Mature Coastal Douglas-fir, Garry oak meadow, rocky outcrops and arbutus stands make up this rare-ecosystem landscape. The park also protects habitat for at-risk birds and headwaters of Excelsior Creek in the Colquitz River system.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-nanaimo-river-regional-park', 'Nanaimo River Regional Park', 'regional', 49.082725, -123.874246, 'Central Island', 'This conservation property protects a remnant of mature Coastal Douglas-fir forest along the lower Nanaimo River. Developed trails provide room to walk and cycle, the river is a swimming spot, and the southeast part is managed as wildlife habitat.', 'https://rdn.bc.ca/spatial-data-files', 'Regional District of Nanaimo — Regional Parks spatial data', NULL, NULL),
    ('regional-osborne-bay-regional-park', 'Osborne Bay Regional Park', 'regional', 48.855811, -123.623265, 'Cowichan Valley', 'This 44-hectare Crofton waterfront park combines calm water, pebble beaches, open fields and nature trails. It offers public shoreline access, picnic space and year-round off-leash dog use.', 'https://maps.cvrd.ca/mapservices/rest/services/Parks/MapServer/2', 'Cowichan Valley Regional District — Parks GIS layer', '980261', NULL),
    ('regional-roche-cove-regional-park', 'Roche Cove Regional Park', 'regional', 48.372623, -123.620204, 'Capital Region', 'Trails wind through temperate rainforest beside a cool creek and sheltered cove. The calm water is also suited to paddling, especially in the quiet morning.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-sandy-pool-regional-park', 'Sandy Pool Regional Park', 'regional', 48.758545, -123.834765, 'Cowichan Valley', 'A sandy beach and swimming holes on the Cowichan River draw summer visitors, while forest paths extend for more than a kilometre and include interpretive signs. The park also has a drift-boat launch and seasonal toilets.', 'https://maps.cvrd.ca/mapservices/rest/services/Parks/MapServer/2', 'Cowichan Valley Regional District — Parks GIS layer', '980395', NULL),
    ('regional-sea-to-sea-regional-park', 'Sea to Sea Regional Park', 'regional', 48.456765, -123.689212, 'Capital Region', 'This nearly 4,000-hectare wilderness area forms part of a protected corridor from Saanich Inlet to Juan de Fuca Strait. High points such as Mount Manuel Quimper and Mount Brule offer expansive views across the Sooke Hills.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-sooke-hills-wilderness-regional-park', 'Sooke Hills Wilderness Regional Park', 'regional', 48.448245, -123.60612, 'Capital Region', 'This large wilderness area borders the Greater Victoria Water Supply Area and includes Mount Braden, one of the highest peaks in the Capital Regional District park system at 471 metres.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-sooke-potholes-regional-park', 'Sooke Potholes Regional Park', 'regional', 48.447059, -123.727756, 'Capital Region', 'Glacially carved pools and smooth rock formations line the Sooke River, where salmon return each fall. Fast-moving water shaped the potholes in the sandstone valley, making the river’s geology the park’s central feature.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-sooke-river-regional-park', 'Sooke River Park', 'regional', 48.389814, -123.702495, 'Capital Region', 'No visitor overview is available in the CRD parks map layer; it identifies the mapped park name and feature.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-st-john-point-regional-park', 'St. John Point Regional Park', 'regional', 48.817716, -123.236838, 'Gulf Islands', 'This North Pender waterfront park has two beaches, an informal perimeter route and a more rugged path along rocky bluffs. It is a quiet place for a coastal walk and birdwatching.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-stoney-hill-regional-park', 'Stoney Hill Regional Park', 'regional', 48.782682, -123.568625, 'Cowichan Valley', 'A 3.2-kilometre loop climbs through the forest above Sansum Narrows, with views toward Salt Spring Island and the surrounding coast. The trail begins and ends at the parking area, which holds about 25 vehicles.', 'https://maps.cvrd.ca/mapservices/rest/services/Parks/MapServer/2', 'Cowichan Valley Regional District — Parks GIS layer', '980399', NULL),
    ('regional-thetis-lake-regional-park', 'Thetis Lake Regional Park', 'regional', 48.481234, -123.477401, 'Capital Region', 'Thetis Lake is a popular swimming and walking destination with more than 40 kilometres of recreation trails. Designated as Canada’s first nature sanctuary in 1958, the park combines protected natural areas with a broad trail network.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-witty-s-lagoon-regional-park', 'Witty''s Lagoon Regional Park', 'regional', 48.385708, -123.517546, 'Capital Region', 'Woodland trails lead through a varied seashore landscape of creek, salt marsh, sandy beach and rocky headlands. The mix of habitats supports abundant birdlife and other wildlife.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL),
    ('regional-wrigglesworth-lake-regional-park', 'Wrigglesworth Lake Regional Park', 'regional', 48.520434, -123.573165, 'Capital Region', 'A trail from Goldstream Heights Drive leads to the lake in this small park beside Sooke Hills Wilderness Regional Park. The lake is the focal point of the visit.', 'https://mapservices.crd.bc.ca/arcgis/rest/services/Basemap/Basemap/MapServer/3', 'Capital Regional District — Park GIS layer', NULL, NULL)
